import React from 'react';
import {AbsoluteFill, Easing, interpolate, clamp, useS, en, golpe, sacudida, ventana, Fondo, Etiqueta, Contador, Camara, Destello, Ondas, FONT} from './kit';
export const SUBS = {acento: '#E7FF00'};
const LIMA = '#E7FF00';
const CIAN = '#7fe6ff';
const NARANJA = '#ffb05a';
const TINTA = '#1a1a3a';
const ANIMAL = en('animal');
const TRAJE = en('traje');
const SE = en('Se');
const TARDI = en('tardígrado');
const ARROZ = en('arroz');
const EN2 = en('En', 2);
const SIETE = en('siete');
const ESPACIO2 = en('espacio', 2);
const DIEZ = en('diez');
const VACIO = en('vacío');
const AIRE = en('aire');
const IBAN = en('Iban');
const VEINTI = en('veinticinco');
const AVION = en('avión');
const SU = en('Su');
const TRUCO = en('truco');
const SECARON = en('secaron');
const ENCOGEN = en('encogen');
const BOLITA = en('bolita');
const APAGA = en('apaga');
const COMER = en('comer');
const AGUA2 = en('agua', 2);
const AL2 = en('Al', 2);
const AGUA3 = en('agua', 3);
const DESPERTO = en('despertó');
const SOL = en('sol');
const ALGUNOS = en('algunos');
const HUEVOS = en('huevos');
const CRIAS = en('crías');
const ENVIA = en('Envíaselo');
const WIFI = en('wifi');
const Defs: React.FC = () => (
<defs>
<radialGradient id='v3cuerpo' cx='35%' cy='28%' r='80%'>
<stop offset='0%' stopColor='#fff1e2' />
<stop offset='55%' stopColor='#f0c3a4' />
<stop offset='100%' stopColor='#a8684e' />
</radialGradient>
<radialGradient id='v3seco' cx='35%' cy='28%' r='80%'>
<stop offset='0%' stopColor='#e9d3a8' />
<stop offset='60%' stopColor='#b08a5a' />
<stop offset='100%' stopColor='#5e4228' />
</radialGradient>
<radialGradient id='v3tierra' cx='40%' cy='20%' r='80%'>
<stop offset='0%' stopColor='#5fc0ff' />
<stop offset='45%' stopColor='#1d6fc0' />
<stop offset='100%' stopColor='#0a2a5a' />
</radialGradient>
<linearGradient id='v3metal' x1='0' y1='0' x2='1' y2='1'>
<stop offset='0%' stopColor='#f2f6ff' />
<stop offset='50%' stopColor='#9fb0c8' />
<stop offset='100%' stopColor='#4a5872' />
</linearGradient>
<radialGradient id='v3arroz' cx='35%' cy='30%' r='75%'>
<stop offset='0%' stopColor='#ffffff' />
<stop offset='70%' stopColor='#efe8d6' />
<stop offset='100%' stopColor='#b8ac8a' />
</radialGradient>
<radialGradient id='v3agua' cx='35%' cy='30%' r='75%'>
<stop offset='0%' stopColor='#e8fbff' />
<stop offset='60%' stopColor='#7fd6ff' />
<stop offset='100%' stopColor='#2a8ac0' />
</radialGradient>
<linearGradient id='v3mesa' x1='0' y1='0' x2='0' y2='1'>
<stop offset='0%' stopColor='#2c4a78' />
<stop offset='100%' stopColor='#0e1a34' />
</linearGradient>
<filter id='v3borroso'><feGaussianBlur stdDeviation='14' /></filter>
<filter id='v3brillo'><feGaussianBlur stdDeviation='9' /></filter>
<filter id='v3lejos'><feGaussianBlur stdDeviation='4' /></filter>
</defs>
);
const Tardigrado: React.FC<{x: number; y: number; esc: number; s: number; seco?: number; dormido?: number; rot?: number; saluda?: number}> = ({x, y, esc, s, seco = 0, dormido = 0, rot = 0, saluda = 0}) => {
const patas = 1 - seco;
const largo = 230 - 130 * seco;
const alto = 120 + 20 * seco;
return (
<g transform={`translate(${x} ${y}) rotate(${rot}) scale(${esc})`}>
<ellipse cx={10} cy={alto + 40} rx={largo * 0.9} ry={20} fill='rgba(0,0,0,0.35)' filter='url(#v3brillo)' />
{/* patas: 4 pares, con garras */}
{[-150, -60, 30, 120].map((px, i) =>
[0, 1].map((lado) => {
const mov = Math.sin(s * 7 + i * 1.3 + lado * 2) * 14 * patas + (i === 3 && lado === 0 ? saluda * Math.sin(s * 12) * 30 : 0);
const lx = px * (1 - 0.55 * seco) + (lado ? 22 : -10);
const ly = alto * 0.55;
const largoPata = 70 * patas;
if (largoPata < 4) return null;
return (
<g key={i + '-' + lado} opacity={lado ? 1 : 0.8}>
<path d={`M ${lx} ${ly - 10} q ${mov} ${largoPata * 0.6} ${mov * 0.6} ${largoPata}`} stroke={lado ? '#d9a385' : '#b98266'} strokeWidth={34} strokeLinecap='round' fill='none' />
{[-10, 0, 10].map((g) => (
<path key={g} d={`M ${lx + mov * 0.6 + g} ${ly - 10 + largoPata} l ${g * 0.6} 16`} stroke='#5a3a2a' strokeWidth={4} strokeLinecap='round' />
))}
</g>
);
}),
)}
{/* cuerpo segmentado */}
<ellipse cx={0} cy={0} rx={largo} ry={alto} fill={seco > 0.5 ? 'url(#v3seco)' : 'url(#v3cuerpo)'} stroke='#8a5038' strokeWidth={5} />
{[-0.55, -0.15, 0.25, 0.62].map((k, i) => (
<path key={i} d={`M ${k * largo} ${-alto * 0.92} Q ${k * largo + 18} 0 ${k * largo} ${alto * 0.92}`} stroke='rgba(138,80,56,0.35)' strokeWidth={6} fill='none' />
))}
{seco > 0.3 &&
Array.from({length: 7}).map((_, i) => (
<path key={'a' + i} d={`M ${-largo * 0.7 + i * largo * 0.22} ${-alto * 0.4 + (i % 2) * 30} q 20 ${-12} 40 0`} stroke='rgba(70,45,25,0.5)' strokeWidth={4} fill='none' opacity={seco} />
))}
<ellipse cx={-largo * 0.35} cy={-alto * 0.55} rx={largo * 0.32} ry={alto * 0.18} fill='#fff' opacity={0.45} />
{/* cabeza con boca de tubo */}
<g transform={`translate(${largo * 0.88} ${-alto * 0.1})`}>
<circle r={alto * 0.62} fill={seco > 0.5 ? 'url(#v3seco)' : 'url(#v3cuerpo)'} stroke='#8a5038' strokeWidth={5} />
<ellipse cx={alto * 0.42} cy={alto * 0.12} rx={14} ry={18} fill='#8a4a3a' />
<ellipse cx={alto * 0.44} cy={alto * 0.12} rx={6} ry={9} fill={TINTA} />
{dormido > 0.5 || seco > 0.5 ? (
<path d={`M ${-6} ${-alto * 0.2} q 12 8 24 0`} stroke={TINTA} strokeWidth={6} fill='none' strokeLinecap='round' />
) : (
<g>
<circle cx={6} cy={-alto * 0.2} r={11} fill={TINTA} />
<circle cx={10} cy={-alto * 0.24} r={4} fill='#fff' />
</g>
)}
<ellipse cx={-alto * 0.1} cy={alto * 0.12} rx={14} ry={8} fill='rgba(255,110,130,0.4)' />
</g>
</g>
);
};
const Orbita: React.FC<{cierre: boolean}> = ({cierre}) => {
const {s, spr, lin} = useS();
const flota = Math.sin(s * 1.6) * 18;
const casco = spr(TRAJE - 0.05, 10, 200) * lin(TRAJE + 0.9, TRAJE + 1.3, 1, 0);
const tacha = lin(TRAJE + 0.3, TRAJE + 0.55, 0, 1);
const capsula = cierre ? 0 : spr(ESPACIO2 - 0.1, 12, 90);
const abre = lin(DIEZ - 0.3, DIEZ + 0.3, 0, 1);
const regla = lin(IBAN - 0.1, IBAN + 0.5, 0, 1);
const marca = interpolate(s, [VEINTI, VEINTI + 1], [0.04, 1], {...clamp, easing: Easing.out(Easing.cubic)});
const wifi = spr(WIFI - 0.1, 10, 200);
const enAnimal = cierre ? 1 : 1 - lin(EN2, EN2 + 0.01, 0, 1);
const anio = spr(SIETE - 0.05, 12, 170) * lin(DIEZ - 0.3, DIEZ, 1, 0);
return (
<AbsoluteFill>
<svg width={1080} height={1920} viewBox='0 0 1080 1920' style={{position: 'absolute'}}>
<Defs />
{/* estrellas lejanas */}
{Array.from({length: 60}).map((_, i) => (
<circle key={i} cx={(i * 173) % 1080} cy={(i * 389) % 1400} r={1.5 + (i % 3)} fill='#dff6ff' opacity={0.3 + 0.5 * Math.abs(Math.sin(s * 1.3 + i))} />
))}
{/* el Sol arriba a la izquierda */}
<circle cx={70} cy={560} r={160} fill={NARANJA} opacity={0.22} filter='url(#v3borroso)' />
<circle cx={70} cy={560} r={60} fill='#fff6d6' opacity={0.9} />
{/* la Tierra */}
<g transform={`translate(0 ${Math.sin(s * 0.4) * 6})`}>
<circle cx={540} cy={3050} r={1500} fill={CIAN} opacity={0.25} filter='url(#v3borroso)' />
<circle cx={540} cy={3060} r={1460} fill='url(#v3tierra)' />
<path d='M 120 1700 Q 300 1640 420 1690 Q 520 1730 640 1680 M 700 1760 Q 820 1700 980 1740' stroke='#7fe08a' strokeWidth={30} fill='none' opacity={0.55} strokeLinecap='round' />
<circle cx={540} cy={3060} r={1460} fill='none' stroke='#bff3ff' strokeWidth={10} opacity={0.6} />
</g>
{/* regla de altura */}
{regla > 0.01 && !cierre && (
<g opacity={regla * lin(SU - 0.3, SU, 1, 0)}>
<line x1={190} y1={1610} x2={190} y2={1610 - 1050 * regla} stroke='#bff3ff' strokeWidth={6} />
{Array.from({length: 11}).map((_, i) => (
<line key={i} x1={175} y1={1610 - i * 105} x2={205} y2={1610 - i * 105} stroke='#bff3ff' strokeWidth={4} opacity={regla} />
))}
<circle cx={190} cy={1610 - 1050 * marca} r={18} fill={LIMA} />
<g transform={`translate(270 ${1610 - 42 + golpe(s, AVION, 10, 4) * 10})`} opacity={lin(AVION - 0.1, AVION + 0.2, 0, 1)}>
<path d='M -40 0 L 40 0 L 60 -8 L 40 -4 L 10 -4 L -10 -28 L -20 -28 L -6 -4 L -34 -4 L -44 -16 L -52 -16 L -46 0 Z' fill='#fff' />
</g>
</g>
)}
{/* cápsula con la bandeja de tardígrados */}
{capsula > 0.01 && (
<g transform={`translate(620 ${1320 - capsula * 260 + flota * 0.5}) scale(${capsula})`}>
<ellipse cx={0} cy={0} rx={190} ry={170} fill='url(#v3metal)' stroke='#2a3650' strokeWidth={6} />
<ellipse cx={-70} cy={-80} rx={60} ry={30} fill='#fff' opacity={0.5} />
<rect x={-200} y={-12} width={400} height={24} fill='#3a4a6a' />
<g transform={`translate(0 -150) rotate(${-70 * abre} -140 0)`}>
<rect x={-140} y={-18} width={280} height={30} rx={10} fill='url(#v3metal)' stroke='#2a3650' strokeWidth={4} />
</g>
<rect x={-130} y={-170} width={260} height={40} rx={12} fill='#1a2a44' />
{[0, 1, 2, 3, 4].map((k) => (
<ellipse key={k} cx={-100 + k * 50} cy={-150} rx={16} ry={12} fill='url(#v3seco)' />
))}
{s > AIRE &&
Array.from({length: 8}).map((_, k) => {
const t = s - AIRE - k * 0.06;
if (t < 0 || t > 1.2) return null;
return <circle key={'b' + k} cx={-100 + k * 28 + Math.sin(k) * 40 * t} cy={-180 - t * 260} r={14 * (1 - t / 1.2)} fill='none' stroke={CIAN} strokeWidth={4} opacity={1 - t / 1.2} />;
})}
</g>
)}
{/* el tardígrado protagonista flotando */}
{enAnimal > 0 && (
<g>
<Tardigrado x={520} y={980 + flota} esc={1.45} s={s} rot={-8 + Math.sin(s * 0.9) * 6} saluda={cierre ? 1 : 0} />
{casco > 0.01 && (
<g transform={`translate(760 ${720 + flota}) scale(${casco})`}>
<circle r={120} fill='rgba(180,230,255,0.25)' stroke='#e8f6ff' strokeWidth={10} />
<ellipse cx={-40} cy={-50} rx={34} ry={20} fill='#fff' opacity={0.6} />
<line x1={-110} y1={-110} x2={-110 + 220 * tacha} y2={-110 + 220 * tacha} stroke='#ff5a6e' strokeWidth={18} strokeLinecap='round' />
</g>
)}
</g>
)}
{cierre && wifi > 0.01 && (
<g transform={`translate(800 ${700 + flota * 0.3}) scale(${wifi})`}>
<circle r={110} fill='rgba(8,20,40,0.85)' stroke={CIAN} strokeWidth={5} />
{[0, 1, 2].map((k) => (
<path key={k} d={`M ${-30 - k * 22} ${10 - k * 14} Q 0 ${-30 - k * 26} ${30 + k * 22} ${10 - k * 14}`} stroke={CIAN} strokeWidth={10} fill='none' strokeLinecap='round' opacity={0.18} />
))}
<circle cx={0} cy={36} r={10} fill={CIAN} opacity={0.3} />
<line x1={-60} y1={60} x2={60} y2={-60} stroke='#ff5a6e' strokeWidth={12} strokeLinecap='round' />
</g>
)}
{anio > 0.01 && (
<g transform={`translate(540 640) scale(${anio})`}>
<rect x={-220} y={-80} width={440} height={160} rx={30} fill='rgba(6,14,30,0.92)' stroke={LIMA} strokeWidth={6} />
<text x={0} y={42} textAnchor='middle' fontFamily={FONT} fontWeight={800} fontSize={120} fill={LIMA}>2007</text>
</g>
)}
{regla > 0.5 && !cierre && s > VEINTI && s < SU && (
<text x={240} y={1610 - 1050 * marca + 20} fontFamily={FONT} fontWeight={800} fontSize={72} fill={LIMA} opacity={lin(VEINTI, VEINTI + 0.3, 0, 1)}>
×25
</text>
)}
</svg>
<AbsoluteFill style={{opacity: ventana(s, DIEZ - 0.1, IBAN - 0.2)}}>
<Contador desde={0} hasta={10} t0={DIEZ} t1={DIEZ + 1} x={540} y={720} sufijo=' días' color={LIMA} size={72} />
</AbsoluteFill>
<AbsoluteFill style={{opacity: ventana(s, VACIO, IBAN - 0.2)}}>
<Etiqueta texto='vacío' x={860} y={760} px={700} py={1000} t0={VACIO} size={36} color={CIAN} />
</AbsoluteFill>
<Ondas x={760} y={720} t0={TRAJE} color='#ff5a6e' radio={300} />
<Ondas x={800} y={700} t0={WIFI} color={CIAN} radio={260} />
</AbsoluteFill>
);
};
const Mesa: React.FC = () => {
const {s, spr, lin} = useS();
const bicho = spr(TARDI - 0.1, 12, 160);
const arroz = spr(ARROZ - 0.05, 10, 180);
const fase2 = s > AL2;
const gota = lin(AGUA3 - 0.2, AGUA3 + 0.35, 0, 1, Easing.in(Easing.quad));
const hincha = lin(DESPERTO - 0.2, DESPERTO + 0.5, 1, 0, Easing.out(Easing.back(1.6)));
const sol = spr(SOL - 0.05, 10, 160);
const huevos = spr(HUEVOS - 0.05, 10, 200);
const nace = lin(CRIAS, CRIAS + 0.5, 0, 1);
return (
<AbsoluteFill>
<svg width={1080} height={1920} viewBox='0 0 1080 1920' style={{position: 'absolute'}}>
<Defs />
{/* fondo: estantes de laboratorio desenfocados */}
<g filter='url(#v3lejos)' opacity={0.5}>
{Array.from({length: 7}).map((_, i) => (
<rect key={i} x={40 + i * 150} y={420 + (i % 2) * 40} width={60} height={160 - (i % 3) * 30} rx={20} fill={['#3a6ab0', '#2a4a80', '#4a8ac0'][i % 3]} />
))}
<rect x={0} y={600} width={1080} height={16} fill='#2a4a80' />
</g>
<path d='M -40 1250 L 1120 1250 L 1120 1960 L -40 1960 Z' fill='url(#v3mesa)' />
<rect x={-40} y={1250} width={1160} height={10} fill={CIAN} opacity={0.3} />
{/* placa de Petri */}
<ellipse cx={540} cy={1260} rx={420} ry={110} fill='rgba(0,0,0,0.4)' filter='url(#v3borroso)' />
<ellipse cx={540} cy={1200} rx={420} ry={120} fill='rgba(200,240,255,0.12)' stroke='#d8f4ff' strokeWidth={6} />
<ellipse cx={420} cy={1150} rx={140} ry={20} fill='#fff' opacity={0.25} />
{!fase2 && (
<g>
{/* lente de aumento */}
<g transform={`translate(400 980) scale(${bicho * 0.85})`}>
<circle r={260} fill='rgba(20,40,70,0.65)' stroke='#e8f6ff' strokeWidth={14} />
<path d='M 180 180 L 320 320' stroke='#6a7a9a' strokeWidth={46} strokeLinecap='round' />
<ellipse cx={-110} cy={-150} rx={70} ry={34} fill='#fff' opacity={0.25} transform='rotate(-30 -110 -150)' />
<Tardigrado x={-20} y={0} esc={0.7} s={s} />
</g>
{/* grano de arroz al lado */}
<g transform={`translate(860 ${1180 - (1 - arroz) * 300}) rotate(${-20 + (1 - arroz) * 60}) scale(${arroz})`}>
<ellipse cx={8} cy={60} rx={160} ry={20} fill='rgba(0,0,0,0.4)' filter='url(#v3brillo)' />
<ellipse cx={0} cy={0} rx={170} ry={62} fill='url(#v3arroz)' stroke='#9a8a62' strokeWidth={5} />
<ellipse cx={-50} cy={-24} rx={70} ry={14} fill='#fff' opacity={0.8} />
</g>
{/* el tardígrado real, del tamaño de un punto al lado del arroz */}
<circle cx={680} cy={1215} r={9} fill='#ffd0b0' stroke='#8a5038' strokeWidth={2} opacity={arroz} />
<line x1={680} y1={1215} x2={560} y2={1150} stroke='#e8f6ff' strokeWidth={3} opacity={arroz * 0.8} strokeDasharray='8 8' />
</g>
)}
{fase2 && (
<g>
{/* gota que cae */}
{gota < 1 && (
<g transform={`translate(540 ${300 + gota * 760})`}>
<path d='M 0 -60 C 30 -10 46 20 40 40 C 30 70 -30 70 -40 40 C -46 20 -30 -10 0 -60 Z' fill='url(#v3agua)' stroke='#2a8ac0' strokeWidth={4} />
<ellipse cx={-12} cy={20} rx={10} ry={16} fill='#fff' opacity={0.7} />
</g>
)}
{gota >= 1 && <ellipse cx={540} cy={1150} rx={300} ry={70} fill='url(#v3agua)' opacity={0.45} />}
<Tardigrado x={520} y={1060} esc={0.95 - 0.25 * hincha} s={s} seco={hincha} />
{/* fila del sol sin filtro */}
{sol > 0.01 && (
<g>
<g transform={`translate(830 800) scale(${sol}) rotate(${s * 30})`}>
{Array.from({length: 12}).map((_, i) => (
<rect key={i} x={-8} y={-150} width={16} height={50} rx={8} fill='#ffd36a' transform={`rotate(${i * 30})`} />
))}
<circle r={90} fill='#ffe28a' />
<circle r={140} fill='#ffcf5a' opacity={0.3} filter='url(#v3brillo)' />
</g>
{Array.from({length: 5}).map((_, k) => {
const vive = k === 1 || k === 3;
const desp = vive ? lin(ALGUNOS, ALGUNOS + 0.5, 1, 0) : 1;
return (
<g key={k} opacity={sol * lin(HUEVOS - 0.3, HUEVOS, 1, 0)}>
<Tardigrado x={200 + k * 170} y={1420} esc={0.32} s={s} seco={desp} dormido={vive ? 0 : 1} />
</g>
);
})}
</g>
)}
{/* huevos y crías */}
{huevos > 0.01 &&
[0, 1, 2].map((k) => {
const x = 780 + k * 70;
const y = 1180 + (k % 2) * 30;
const roto = lin(CRIAS + k * 0.15, CRIAS + k * 0.15 + 0.2, 0, 1);
return (
<g key={k} transform={`translate(${x} ${y}) scale(${huevos})`}>
{roto < 1 && (
<g opacity={1 - roto}>
<ellipse cx={0} cy={0} rx={30} ry={38} fill='url(#v3arroz)' stroke='#9a8a62' strokeWidth={4} />
