)}
{nace > 0 && <Tardigrado x={0} y={-10 - roto * 30} esc={0.22 * roto} s={s} />}
</g>
);
})}
</g>
)}
</svg>
<AbsoluteFill style={{opacity: ventana(s, ARROZ, EN2 - 0.2)}}>
<Etiqueta texto='tardígrado' x={620} y={1380} px={680} py={1222} t0={ARROZ + 0.3} size={34} />
</AbsoluteFill>
<Ondas x={540} y={1150} t0={AGUA3 + 0.35} color={CIAN} radio={500} />
<Ondas x={520} y={1060} t0={DESPERTO} color={LIMA} radio={420} />
</AbsoluteFill>
);
};
const PrimerPlano: React.FC = () => {
const {s, spr, lin} = useS();
const seco = lin(ENCOGEN - 0.1, BOLITA + 0.2, 0, 1);
const vapor = s > SECARON - 0.1 && s < BOLITA + 0.5;
const actividad = interpolate(s, [APAGA - 0.2, APAGA + 0.8], [1, 0.06], clamp);
const medidor = spr(APAGA - 0.3, 12, 160);
const brillo = Math.max(0, 1 - Math.abs(s - TRUCO - 0.1) * 2.5);
const gota = lin(AGUA2 - 0.2, AGUA2 + 0.6, 0, 1, Easing.in(Easing.quad));
return (
<AbsoluteFill>
<svg width={1080} height={1920} viewBox='0 0 1080 1920' style={{position: 'absolute'}}>
<Defs />
{/* fondo micro: musgo desenfocado */}
<g filter='url(#v3lejos)' opacity={0.45}>
{Array.from({length: 10}).map((_, i) => (
<ellipse key={i} cx={(i * 211) % 1080} cy={1500 + (i % 3) * 80} rx={160} ry={60} fill={['#2a7a6a', '#1f5a6a', '#3a8a7a'][i % 3]} />
))}
</g>
<circle cx={540} cy={1060} r={420} fill={CIAN} opacity={0.1 + 0.3 * brillo} filter='url(#v3borroso)' />
<Tardigrado x={500 - 40 * seco} y={1060} esc={1.7 - 0.2 * seco} s={s} seco={seco} />
{vapor &&
Array.from({length: 10}).map((_, k) => {
const t = (s - SECARON - k * 0.12) % 1.3;
if (t < 0) return null;
return (
<path key={k} d={`M ${300 + k * 50} ${1000 - t * 300} q 14 -20 0 -40 q -14 -20 0 -40`} stroke='#d8f4ff' strokeWidth={8} fill='none' opacity={(1 - t / 1.3) * 0.7} strokeLinecap='round' />
);
